  // ── the suite must not litter the directory it was run from ──────────────
  //
  // Every artifact goes through tempPath() now, but the way that rule breaks
  // is invisible: a relative name works, the file is written, the test passes,
  // and the mess only surfaces in somebody's `git status` weeks later -- which
  // is how three of these ended up sitting in the working tree of the
  // repository that vendors the SDK, belonging to no commit. So the rule is
  // MEASURED at the end of the run, on the platform where a failed
  // std::remove is silent as much as on the one where it is not.
  {
    std::vector<std::string> stray;
    std::error_code ec;
    const std::filesystem::path here = std::filesystem::current_path(ec);
    if (!ec) {
      for (const auto& entry : std::filesystem::directory_iterator(here, ec)) {
        const std::string leaf = entry.path().filename().string();
        if (leaf.rfind("sonore-", 0) == 0) stray.push_back(leaf);
      }
    }
    for (const std::string& leaf : stray) std::printf("       left behind: %s\n", leaf.c_str());
    check(stray.empty(), "the suite left no files in the directory it ran from");
  }



  std::printf("\n%d checks, %d failure(s)\n", g_checks, g_failures);
  if (g_failures == 0) std::printf("SONORE SDK TESTS PASSED\n");
  return g_failures == 0 ? 0 : 1;
